def ticker():
    t = iter(range(0, 100, 5))
    return lambda: next(t)

def test_logs():
    log = []
    with timed("call", log, ticker()):
        pass
    assert log == [("call", 5)]

def test_logs_on_error():
    log = []
    try:
        with timed("bad", log, ticker()):
            raise RuntimeError("boom")
    except RuntimeError:
        pass
    assert log == [("bad", 5)], "finally must run even when the block raises"

